  const yearRange = text.match(/(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*years?/);
  if (yearRange) return Number(((Number(yearRange[1]) + Number(yearRange[2])) / 2).toFixed(2));
